#!/usr/bin/env python3
"""Mutation fuzzer for invalid-input handling: compare main.py vs ref.py."""
import sys, json, random, copy, importlib.util
sys.path.insert(0, '/workspace/tmp')
import gen, gen2, gen3

def load(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m

main_mod = load('/workspace/submission/main.py', 'subm')
ref_mod = load('/workspace/tmp/ref.py', 'refm')

def strict_loads(text):
    def hook(pairs):
        d = {}
        for k, v in pairs:
            if k in d: raise ValueError('dup')
            d[k] = v
        return d
    def bf(s): raise ValueError('float')
    def bc(s): raise ValueError('const')
    return json.loads(text, parse_float=bf, parse_constant=bc, object_pairs_hook=hook)

def run_main(text):
    try:
        return json.loads(json.dumps(main_mod.run(text)))
    except Exception:
        return {"error": "invalid-input"}

def run_ref(text):
    try:
        doc = strict_loads(text)
        cfg, mdl, conns, pkts = ref_mod.check(doc)
        return json.loads(json.dumps(ref_mod.replay(cfg, mdl, conns, pkts)))
    except Exception:
        return {"error": "invalid-input"}

ERR = {"error": "invalid-input"}

def rand_path(obj, r, path=()):
    """Pick a random nested dict/list location."""
    for _ in range(30):
        if isinstance(obj, dict) and obj:
            k = r.choice(list(obj.keys()))
            path = path + (k,)
            obj = obj[k]
        elif isinstance(obj, list) and obj:
            i = r.randrange(len(obj))
            path = path + (i,)
            obj = obj[i]
        else:
            break
        if r.random() < 0.35:
            break
    return path

def getp(doc, path):
    o = doc
    for p in path: o = o[p]
    return o

def setp(doc, path, val):
    o = doc
    for p in path[:-1]: o = o[p]
    o[path[-1]] = val

def mutate(doc, r):
    doc = copy.deepcopy(doc)
    kind = r.randrange(14)
    path = rand_path(doc, r)
    if not path: return doc, 'noop'
    try:
        cur = getp(doc, path)
    except Exception:
        return doc, 'noop'
    if kind == 0:                      # delete key
        if isinstance(cur, dict) and cur:
            del cur[r.choice(list(cur.keys()))]
            return doc, 'delkey'
    if kind == 1:                      # add extra key
        if isinstance(cur, dict):
            cur['zzz_extra'] = 1
            return doc, 'extrakey'
    if kind == 2:                      # wrong scalar type
        setp(doc, path, r.choice([True, False, 1.5, "3", None, [], {}, 1e3]))
        return doc, 'type'
    if kind == 3:                      # out of range
        if isinstance(cur, int) and not isinstance(cur, bool):
            setp(doc, path, r.choice([cur + 10**15, -(10**15), -cur - 1,
                                      2**70, cur * 10**6 + 7]))
            return doc, 'range'
    if kind == 4:                      # array length change
        if isinstance(cur, list):
            if r.random() < 0.5 and cur: cur.pop()
            else: cur.append(copy.deepcopy(cur[0]) if cur else 0)
            return doc, 'len'
    if kind == 5:                      # swap array elements
        if isinstance(cur, list) and len(cur) > 1:
            i, j = r.sample(range(len(cur)), 2)
            cur[i], cur[j] = cur[j], cur[i]
            return doc, 'swap'
    if kind == 6 and doc['version'] is not None:
        doc['version'] = r.choice([0, 2, "1", 1.0, True, None])
        return doc, 'version'
    if kind == 7:                      # break packet time order
        pk = doc['packets']
        if len(pk) > 1:
            i = r.randrange(len(pk) - 1)
            pk[i + 1]['time'] = max(0, pk[i]['time'] - r.randint(1, 5))
            return doc, 'timeorder'
    if kind == 8:                      # unknown / bad connection id
        if doc['packets']:
            doc['packets'][r.randrange(len(doc['packets']))]['connection'] = \
                r.choice(['nope', '', 'a' * 33, 'bad id', 5, None])
            return doc, 'unknownconn'
    if kind == 9:                      # duplicate connection ids
        cs = doc['connections']
        if len(cs) > 1:
            cs[1]['id'] = cs[0]['id']
            return doc, 'dupid'
    if kind == 10:                     # split value
        cs = doc['connections']
        if cs: cs[r.randrange(len(cs))]['split'] = r.choice(['train', 'DEV', '', 3, None])
        return doc, 'split'
    if kind == 11:                     # kernel > window
        doc['model']['kernel'] = doc['config']['window'] + 1
        if doc['model']['kernel'] > 5:
            doc['config']['window'] = max(1, doc['model']['kernel'] - 2)
            doc['model']['kernel'] = min(5, doc['config']['window'] + 1)
            if doc['model']['kernel'] <= doc['config']['window']:
                return doc, 'noop'
        return doc, 'kernelwindow'
    if kind == 12:                     # initial_tokens > bucket_capacity
        doc['config']['initial_tokens'] = doc['config']['bucket_capacity'] + 1
        return doc, 'tokens'
    if kind == 13:                     # probability shape
        p = doc['config']['probability']
        if p:
            if r.random() < 0.5: p.pop()
            else: p.append(p[0])
        return doc, 'probshape'
    return doc, 'noop'

def text_mutate(text, r):
    kind = r.randrange(10)
    if kind == 0: return text[:-r.randint(1, 5)]
    if kind == 1: return text + ']'
    if kind == 2: return text.replace('"version"', '"version"', 1) + ' '
    if kind == 3: return '{' + text[1:]
    if kind == 4: return text.replace('1', 'NaN', 1) if '1' in text else text
    if kind == 5: return text.replace('0', 'Infinity', 1)
    if kind == 6:
        i = text.find('"config"')
        return text[:i] + '"config": 5, ' + text[i + len('"config"'):] if i >= 0 else text
    if kind == 7:
        i = text.find('"slots"')
        if i < 0: return text
        j = text.find(',', i)
        seg = text[i:j]
        return text[:i] + seg + ', ' + seg + text[j:]      # duplicate key
    if kind == 8:
        i = text.find(':')
        return text[:i] + ': 07' + text[i + 1:]
    return text + '  '

def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    r = random.Random(12345)
    kinds = {}
    bad = 0
    for seed in range(lo, hi):
        g = (gen, gen2, gen3)[seed % 3]
        doc = g.gen(seed)
        for _ in range(6):
            m, kind = mutate(doc, r)
            text = json.dumps(m)
            a, b = run_main(text), run_ref(text)
            kinds[kind] = kinds.get(kind, 0) + (1 if a == ERR else 0)
            if a != b:
                bad += 1
                print('MISMATCH', kind, 'seed', seed)
                print('  got', json.dumps(a)[:300])
                print('  exp', json.dumps(b)[:300])
                open('/workspace/tmp/bad_%d.json' % seed, 'w').write(text)
                if bad > 5: return
        text = json.dumps(doc)
        for _ in range(3):
            t2 = text_mutate(text, r)
            a, b = run_main(t2), run_ref(t2)
            if a != b:
                bad += 1
                print('TEXT MISMATCH seed', seed, repr(t2[:200]))
                print('  got', json.dumps(a)[:200], 'exp', json.dumps(b)[:200])
                if bad > 5: return
    print('mutation kinds rejected by main:', json.dumps(kinds, sort_keys=True))
    print('mismatches:', bad)

main()
